/**
 * Result of a public delete, membership removal, or session revocation.
 * Default requests return NOT_FOUND for a missing target. With allow_missing,
 * only a missing target becomes ALREADY_ABSENT; parent lookup, authorization,
 * validation, precondition, and backend errors retain their normal status.
 * These results describe the targeted resource, not a same-name replacement.
 */
export const DeletionOutcome = {
  /** DELETION_OUTCOME_UNSPECIFIED - No outcome was supplied. Never infer completion from this value. */
  DELETION_OUTCOME_UNSPECIFIED: "DELETION_OUTCOME_UNSPECIFIED",
  /**
   * DELETION_OUTCOME_COMPLETED - The targeted gateway resource is removed (or the SSH session is revoked).
   * Downstream platform garbage collection may still be finishing.
   */
  DELETION_OUTCOME_COMPLETED: "DELETION_OUTCOME_COMPLETED",
  /**
   * DELETION_OUTCOME_ACCEPTED - Sandbox deletion is accepted but its gateway record still exists.
   * Observe the targeted sandbox ID until it disappears for completion.
   */
  DELETION_OUTCOME_ACCEPTED: "DELETION_OUTCOME_ACCEPTED",
  /** DELETION_OUTCOME_ALREADY_ABSENT - The target did not exist and allow_missing was true. */
  DELETION_OUTCOME_ALREADY_ABSENT: "DELETION_OUTCOME_ALREADY_ABSENT",
} as const;

export type DeletionOutcome = typeof DeletionOutcome[keyof typeof DeletionOutcome];

export namespace DeletionOutcome {
  export type DELETION_OUTCOME_UNSPECIFIED = typeof DeletionOutcome.DELETION_OUTCOME_UNSPECIFIED;
  export type DELETION_OUTCOME_COMPLETED = typeof DeletionOutcome.DELETION_OUTCOME_COMPLETED;
  export type DELETION_OUTCOME_ACCEPTED = typeof DeletionOutcome.DELETION_OUTCOME_ACCEPTED;
  export type DELETION_OUTCOME_ALREADY_ABSENT = typeof DeletionOutcome.DELETION_OUTCOME_ALREADY_ABSENT;
}

/**
 * Last observed network result for a configured external tool endpoint.
 * Results describe accepted traffic observations, not present availability.
 */
export const EndpointResult = {
  ENDPOINT_RESULT_UNSPECIFIED: "ENDPOINT_RESULT_UNSPECIFIED",
  /** ENDPOINT_RESULT_NO_OBSERVED_EXCHANGE - No exchange has been observed under the current configuration and session. */
  ENDPOINT_RESULT_NO_OBSERVED_EXCHANGE: "ENDPOINT_RESULT_NO_OBSERVED_EXCHANGE",
  /**
   * ENDPOINT_RESULT_HTTP_RESPONSE_RECEIVED - An upstream HTTP status below 400 was received. Its body can still contain
   * an MCP error; this result does not establish tool-call success.
   */
  ENDPOINT_RESULT_HTTP_RESPONSE_RECEIVED: "ENDPOINT_RESULT_HTTP_RESPONSE_RECEIVED",
  /** ENDPOINT_RESULT_POLICY_DENIED - OpenShell policy denied the request locally. */
  ENDPOINT_RESULT_POLICY_DENIED: "ENDPOINT_RESULT_POLICY_DENIED",
  /** ENDPOINT_RESULT_CREDENTIAL_UNAVAILABLE - An applicable OpenShell-managed credential was unavailable. */
  ENDPOINT_RESULT_CREDENTIAL_UNAVAILABLE: "ENDPOINT_RESULT_CREDENTIAL_UNAVAILABLE",
  /** ENDPOINT_RESULT_TLS_FAILED - TLS setup for the upstream connection failed. */
  ENDPOINT_RESULT_TLS_FAILED: "ENDPOINT_RESULT_TLS_FAILED",
  /** ENDPOINT_RESULT_TRANSPORT_FAILED - The upstream transport failed before an HTTP response arrived. */
  ENDPOINT_RESULT_TRANSPORT_FAILED: "ENDPOINT_RESULT_TRANSPORT_FAILED",
  /** ENDPOINT_RESULT_UPSTREAM_REJECTED - The upstream service returned an HTTP rejection. */
  ENDPOINT_RESULT_UPSTREAM_REJECTED: "ENDPOINT_RESULT_UPSTREAM_REJECTED",
} as const;

export type EndpointResult = typeof EndpointResult[keyof typeof EndpointResult];

export namespace EndpointResult {
  export type ENDPOINT_RESULT_UNSPECIFIED = typeof EndpointResult.ENDPOINT_RESULT_UNSPECIFIED;
  export type ENDPOINT_RESULT_NO_OBSERVED_EXCHANGE = typeof EndpointResult.ENDPOINT_RESULT_NO_OBSERVED_EXCHANGE;
  export type ENDPOINT_RESULT_HTTP_RESPONSE_RECEIVED = typeof EndpointResult.ENDPOINT_RESULT_HTTP_RESPONSE_RECEIVED;
  export type ENDPOINT_RESULT_POLICY_DENIED = typeof EndpointResult.ENDPOINT_RESULT_POLICY_DENIED;
  export type ENDPOINT_RESULT_CREDENTIAL_UNAVAILABLE = typeof EndpointResult.ENDPOINT_RESULT_CREDENTIAL_UNAVAILABLE;
  export type ENDPOINT_RESULT_TLS_FAILED = typeof EndpointResult.ENDPOINT_RESULT_TLS_FAILED;
  export type ENDPOINT_RESULT_TRANSPORT_FAILED = typeof EndpointResult.ENDPOINT_RESULT_TRANSPORT_FAILED;
  export type ENDPOINT_RESULT_UPSTREAM_REJECTED = typeof EndpointResult.ENDPOINT_RESULT_UPSTREAM_REJECTED;
}

